import React, { useEffect, useState, useMemo } from 'react';
import api from '../services/api';
import ProfModal from './ProfModal';

const VILLES = ['Tunis','Sfax','Sousse','Monastir','Nabeul','Bizerte','Kairouan','Ariana','Ben Arous','Mahdia'];

/* ── Helpers ── */
function Stars({ n, size = '.9rem' }) {
  const v = parseFloat(n) || 0;
  return (
    <span style={{ display:'inline-flex', alignItems:'center', gap:2 }}>
      {[1,2,3,4,5].map(i => (
        <span key={i} style={{ color: i <= Math.round(v) ? '#f59e0b' : 'var(--border)', fontSize: size, lineHeight:1 }}>★</span>
      ))}
      <span style={{ color:'var(--text2)', fontSize:'.75rem', marginLeft:4, fontWeight:600 }}>{v.toFixed(1)}</span>
    </span>
  );
}

function ModeBadge({ mode }) {
  const cfg = {
    en_ligne:   { icon:'🌐', label:'En ligne',   color:'#38bdf8', bg:'rgba(56,189,248,0.12)'  },
    presentiel: { icon:'🏫', label:'Présentiel', color:'#43e97b', bg:'rgba(67,233,123,0.12)'  },
    les_deux:   { icon:'🔀', label:'Les deux',   color:'#6c63ff', bg:'rgba(108,99,255,0.12)' },
  }[mode] || { icon:'🏫', label:'Présentiel', color:'#43e97b', bg:'rgba(67,233,123,0.12)' };
  return (
    <span style={{ display:'inline-flex', alignItems:'center', gap:4, fontSize:'.68rem', fontWeight:700, padding:'3px 9px', borderRadius:20, background:cfg.bg, color:cfg.color }}>
      {cfg.icon} {cfg.label}
    </span>
  );
}

function getTarifMin(prof) {
  const tarifs = [prof.tarif_en_ligne, prof.tarif_presentiel]
    .filter(v => v !== null && v !== undefined && v !== '' && parseFloat(v) > 0)
    .map(Number);
  return tarifs.length ? Math.min(...tarifs) : null;
}

/* ════════════════════════════════════════════════
   CARTE PROFESSEUR — design premium
════════════════════════════════════════════════ */
function ProfCard({ prof, onView }) {
  const [hovered, setHovered] = useState(false);
  const nom      = `${prof.user_prenom || ''} ${prof.user_nom || ''}`.trim() || 'Professeur';
  const matieres = prof.tarifs_matieres ? [...new Set(prof.tarifs_matieres.map(t => t.nom_matiere))].slice(0, 3) : [];
  const tarifMin = getTarifMin(prof);
  const hasMore  = prof.tarifs_matieres && [...new Set(prof.tarifs_matieres.map(t => t.nom_matiere))].length > 3;

  return (
    <div
      onClick={() => onView(prof)}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        background: 'var(--card)', border: hovered ? '1px solid rgba(108,99,255,0.5)' : '1px solid var(--border)',
        borderRadius: 22, overflow: 'hidden', cursor: 'pointer',
        transform: hovered ? 'translateY(-6px)' : 'none',
        boxShadow: hovered ? '0 24px 60px rgba(108,99,255,0.2)' : '0 2px 12px rgba(0,0,0,0.1)',
        transition: 'all .3s cubic-bezier(.34,1.56,.64,1)',
        display: 'flex', flexDirection: 'column',
      }}
    >
      {/* Bandeau + avatar */}
      <div style={{ height: 100, background: hovered ? 'linear-gradient(135deg,rgba(108,99,255,.55),rgba(255,101,132,.4))' : 'linear-gradient(135deg,rgba(108,99,255,.35),rgba(255,101,132,.2))', position: 'relative', transition: 'background .3s' }}>
        {/* Badge mode en haut à droite */}
        <div style={{ position:'absolute', top:10, right:12 }}>
          <ModeBadge mode={prof.mode_enseignement} />
        </div>

        {/* Cercle décoratif */}
        <div style={{ position:'absolute', width:80, height:80, borderRadius:'50%', background:'rgba(255,255,255,0.04)', top:-20, left:60 }} />

        {/* Avatar */}
        <div style={{
          width: 76, height: 76, borderRadius: '50%',
          border: `3px solid var(--card)`,
          background: 'linear-gradient(135deg,#6c63ff,#ff6584)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          fontSize: '1.7rem', overflow: 'hidden',
          position: 'absolute', bottom: -38, left: 20,
          boxShadow: hovered ? '0 10px 30px rgba(108,99,255,0.5)' : '0 4px 16px rgba(0,0,0,0.3)',
          transition: 'box-shadow .3s',
        }}>
          {prof.photo_url
            ? <img src={`http://localhost:8001${prof.photo_url}`} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }} />
            : '👨‍🏫'}
        </div>

        {/* Tarif badge en haut */}
        {tarifMin && (
          <div style={{ position:'absolute', bottom:10, right:12, background:'rgba(0,0,0,0.35)', backdropFilter:'blur(6px)', padding:'4px 10px', borderRadius:20, fontSize:'.72rem', fontWeight:700, color:'#fff' }}>
            À partir de {tarifMin} DT/h
          </div>
        )}
      </div>

      {/* Contenu */}
      <div style={{ padding: '46px 20px 20px', flex: 1, display: 'flex', flexDirection: 'column', gap: 10 }}>

        {/* Nom + ville */}
        <div>
          <div style={{ fontFamily:'Syne', fontWeight:800, fontSize:'1.05rem', marginBottom:3 }}>{nom}</div>
          {prof.ville && (
            <div style={{ display:'flex', alignItems:'center', gap:4, fontSize:'.78rem', color:'var(--text2)' }}>
              <span>📍</span>{prof.ville}
            </div>
          )}
        </div>

        {/* Note */}
        <div style={{ display:'flex', alignItems:'center', gap:8 }}>
          <Stars n={prof.note_moyenne} />
          <span style={{ fontSize:'.73rem', color:'var(--text2)' }}>
            {prof.nb_avis > 0 ? `(${prof.nb_avis} avis)` : 'Nouveau'}
          </span>
        </div>

        {/* Matières */}
        {matieres.length > 0 && (
          <div style={{ display:'flex', flexWrap:'wrap', gap:5 }}>
            {matieres.map(m => (
              <span key={m} style={{ fontSize:'.68rem', fontWeight:600, padding:'3px 9px', borderRadius:20, background:'rgba(108,99,255,0.08)', color:'#6c63ff', border:'1px solid rgba(108,99,255,0.15)' }}>
                {m}
              </span>
            ))}
            {hasMore && (
              <span style={{ fontSize:'.68rem', color:'var(--text2)', padding:'3px 7px' }}>+{[...new Set(prof.tarifs_matieres.map(t => t.nom_matiere))].length - 3}</span>
            )}
          </div>
        )}

        {/* Spacer */}
        <div style={{ flex:1 }} />

        {/* Séparateur */}
        <div style={{ height:1, background:'var(--border)', margin:'0 -0px' }} />

        {/* Footer : stats + bouton */}
        <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', paddingTop:4 }}>
          <div style={{ display:'flex', gap:14 }}>
            {prof.tarif_en_ligne && parseFloat(prof.tarif_en_ligne) > 0 && (
              <div style={{ fontSize:'.72rem', color:'var(--text2)', display:'flex', alignItems:'center', gap:3 }}>
                <span style={{ color:'#38bdf8' }}>🌐</span> {prof.tarif_en_ligne} DT
              </div>
            )}
            {prof.tarif_presentiel && parseFloat(prof.tarif_presentiel) > 0 && (
              <div style={{ fontSize:'.72rem', color:'var(--text2)', display:'flex', alignItems:'center', gap:3 }}>
                <span style={{ color:'#43e97b' }}>🏫</span> {prof.tarif_presentiel} DT
              </div>
            )}
          </div>
          <div style={{
            padding:'6px 14px', borderRadius:20,
            background: hovered ? 'linear-gradient(135deg,#6c63ff,#8b5cf6)' : 'var(--surface2)',
            color: hovered ? '#fff' : 'var(--text2)',
            fontSize:'.75rem', fontWeight:700,
            transition:'all .2s', border:'1px solid var(--border)',
          }}>
            Voir profil →
          </div>
        </div>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════
   CARTE VUE LISTE
════════════════════════════════════════════════ */
function ProfRow({ prof, onView }) {
  const [hovered, setHovered] = useState(false);
  const nom      = `${prof.user_prenom || ''} ${prof.user_nom || ''}`.trim() || 'Professeur';
  const matieres = prof.tarifs_matieres ? [...new Set(prof.tarifs_matieres.map(t => t.nom_matiere))].slice(0, 4) : [];
  const tarifMin = getTarifMin(prof);

  return (
    <div
      onClick={() => onView(prof)}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{ display:'flex', alignItems:'center', gap:16, padding:'16px 20px', background:'var(--card)', border: hovered ? '1px solid rgba(108,99,255,0.4)' : '1px solid var(--border)', borderRadius:16, cursor:'pointer', transition:'all .2s', boxShadow: hovered ? '0 8px 30px rgba(108,99,255,0.12)' : 'none' }}
    >
      <div style={{ width:52, height:52, borderRadius:'50%', background:'linear-gradient(135deg,#6c63ff,#ff6584)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:'1.3rem', overflow:'hidden', flexShrink:0 }}>
        {prof.photo_url ? <img src={`http://localhost:8001${prof.photo_url}`} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }} /> : '👨‍🏫'}
      </div>
      <div style={{ flex:1, minWidth:0 }}>
        <div style={{ display:'flex', alignItems:'center', gap:10, marginBottom:4, flexWrap:'wrap' }}>
          <span style={{ fontFamily:'Syne', fontWeight:800, fontSize:'.95rem' }}>{nom}</span>
          {prof.ville && <span style={{ fontSize:'.72rem', color:'var(--text2)' }}>📍 {prof.ville}</span>}
          <ModeBadge mode={prof.mode_enseignement} />
        </div>
        <div style={{ display:'flex', gap:6, flexWrap:'wrap' }}>
          {matieres.map(m => (
            <span key={m} style={{ fontSize:'.67rem', fontWeight:600, padding:'2px 8px', borderRadius:20, background:'rgba(108,99,255,0.08)', color:'#6c63ff', border:'1px solid rgba(108,99,255,0.15)' }}>{m}</span>
          ))}
        </div>
      </div>
      <div style={{ display:'flex', alignItems:'center', gap:20, flexShrink:0 }}>
        <Stars n={prof.note_moyenne} />
        {tarifMin && <span style={{ fontSize:'.82rem', fontWeight:700, color:'var(--text)' }}>dès {tarifMin} DT/h</span>}
        <div style={{ padding:'7px 16px', background: hovered ? 'linear-gradient(135deg,#6c63ff,#8b5cf6)' : 'var(--surface2)', color: hovered ? '#fff' : 'var(--text2)', borderRadius:20, fontSize:'.78rem', fontWeight:700, transition:'all .2s', border:'1px solid var(--border)' }}>
          Voir →
        </div>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════
   PAGE PRINCIPALE
════════════════════════════════════════════════ */
export default function Profs() {
  const [profs, setProfs]           = useState([]);
  const [loading, setLoading]       = useState(true);
  const [selectedProf, setSelectedProf] = useState(null);
  const [vue, setVue]               = useState('grille'); // 'grille' | 'liste'

  // Filtres
  const [search, setSearch]         = useState('');
  const [filterVille, setFilterVille]   = useState('');
  const [filterMode, setFilterMode]     = useState('');
  const [filterMatiere, setFilterMatiere] = useState('');
  const [filterBudget, setFilterBudget]   = useState('');
  const [sortBy, setSortBy]         = useState('note'); // 'note' | 'tarif_asc' | 'tarif_desc'
  const [showFilters, setShowFilters] = useState(false);

  useEffect(() => {
    api.get('/api/professeurs/')
      .then(r => setProfs(r.data || []))
      .catch(() => setProfs([]))
      .finally(() => setLoading(false));
  }, []);

  // Toutes les matières disponibles
  const allMatieres = useMemo(() => {
    const set = new Set();
    profs.forEach(p => p.tarifs_matieres?.forEach(t => set.add(t.nom_matiere)));
    return [...set].sort();
  }, [profs]);

  // Filtrage + tri
  const filtered = useMemo(() => {
    let list = [...profs];
    const q  = search.toLowerCase().trim();

    if (q) list = list.filter(p => {
      const nom = `${p.user_prenom || ''} ${p.user_nom || ''}`.toLowerCase();
      const mats = (p.tarifs_matieres || []).map(t => t.nom_matiere.toLowerCase()).join(' ');
      return nom.includes(q) || mats.includes(q) || (p.ville || '').toLowerCase().includes(q);
    });

    if (filterVille)   list = list.filter(p => p.ville === filterVille);
    if (filterMode)    list = list.filter(p => p.mode_enseignement === filterMode || p.mode_enseignement === 'les_deux');
    if (filterMatiere) list = list.filter(p => p.tarifs_matieres?.some(t => t.nom_matiere === filterMatiere));
    if (filterBudget) {
      const max = parseInt(filterBudget);
      list = list.filter(p => {
        const min = getTarifMin(p);
        return min !== null && min <= max;
      });
    }

    if (sortBy === 'note')       list.sort((a, b) => (parseFloat(b.note_moyenne) || 0) - (parseFloat(a.note_moyenne) || 0));
    if (sortBy === 'tarif_asc')  list.sort((a, b) => (getTarifMin(a) || 999) - (getTarifMin(b) || 999));
    if (sortBy === 'tarif_desc') list.sort((a, b) => (getTarifMin(b) || 0) - (getTarifMin(a) || 0));

    return list;
  }, [profs, search, filterVille, filterMode, filterMatiere, filterBudget, sortBy]);

  const hasFilters = filterVille || filterMode || filterMatiere || filterBudget;
  const resetFilters = () => { setFilterVille(''); setFilterMode(''); setFilterMatiere(''); setFilterBudget(''); setSearch(''); };

  const inp = { background:'var(--surface2)', border:'1px solid var(--border)', borderRadius:10, color:'var(--text)', padding:'9px 13px', fontSize:'.85rem', outline:'none' };

  if (loading) return (
    <div style={{ padding:60, textAlign:'center', color:'var(--text2)' }}>
      <div style={{ fontSize:'2rem', marginBottom:12 }}>🔍</div>
      Recherche des professeurs...
    </div>
  );

  return (
    <div style={{ padding:32, maxWidth:1300, margin:'0 auto' }}>

      {/* ── HEADER ── */}
      <div style={{ marginBottom:28 }}>
        <h1 style={{ fontFamily:'Syne', fontSize:'1.9rem', fontWeight:800, margin:'0 0 6px' }}>
          Trouver un professeur
        </h1>
        <p style={{ color:'var(--text2)', margin:0, fontSize:'.9rem' }}>
          {profs.length} professeur{profs.length !== 1 ? 's' : ''} disponible{profs.length !== 1 ? 's' : ''} sur la plateforme
        </p>
      </div>

      {/* ── BARRE RECHERCHE + CONTRÔLES ── */}
      <div style={{ display:'flex', gap:12, marginBottom:16, flexWrap:'wrap', alignItems:'center' }}>
        {/* Recherche */}
        <div style={{ position:'relative', flex:1, minWidth:220 }}>
          <span style={{ position:'absolute', left:13, top:'50%', transform:'translateY(-50%)', fontSize:'1rem' }}>🔍</span>
          <input
            style={{ ...inp, paddingLeft:38, width:'100%', boxSizing:'border-box' }}
            placeholder="Nom, matière, ville..."
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>

        {/* Tri */}
        <select style={{ ...inp, minWidth:160 }} value={sortBy} onChange={e => setSortBy(e.target.value)}>
          <option value="note">⭐ Mieux notés</option>
          <option value="tarif_asc">💰 Tarif croissant</option>
          <option value="tarif_desc">💰 Tarif décroissant</option>
        </select>

        {/* Bouton filtres */}
        <button
          onClick={() => setShowFilters(!showFilters)}
          style={{ padding:'9px 16px', background: hasFilters ? 'rgba(108,99,255,0.15)' : 'var(--surface2)', border: hasFilters ? '1px solid rgba(108,99,255,0.4)' : '1px solid var(--border)', borderRadius:10, cursor:'pointer', color: hasFilters ? '#6c63ff' : 'var(--text)', fontWeight:600, fontSize:'.85rem', display:'flex', alignItems:'center', gap:6 }}
        >
          🔧 Filtres {hasFilters && <span style={{ background:'#6c63ff', color:'#fff', fontSize:'.65rem', padding:'1px 6px', borderRadius:20 }}>●</span>}
        </button>

        {/* Vue grille/liste */}
        <div style={{ display:'flex', border:'1px solid var(--border)', borderRadius:10, overflow:'hidden' }}>
          {[['grille','⊞'], ['liste','≡']].map(([v, icon]) => (
            <button key={v} onClick={() => setVue(v)}
              style={{ padding:'9px 14px', background: vue === v ? 'rgba(108,99,255,0.15)' : 'var(--surface2)', border:'none', cursor:'pointer', color: vue === v ? '#6c63ff' : 'var(--text2)', fontWeight:600, fontSize:'1rem', transition:'all .15s' }}>
              {icon}
            </button>
          ))}
        </div>
      </div>

      {/* ── FILTRES AVANCÉS ── */}
      {showFilters && (
        <div style={{ background:'var(--card)', border:'1px solid var(--border)', borderRadius:16, padding:20, marginBottom:20, display:'grid', gridTemplateColumns:'repeat(auto-fill, minmax(180px, 1fr))', gap:14, animation:'fadeDown .2s ease' }}>
          <style>{`@keyframes fadeDown{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:translateY(0)}}`}</style>

          <div>
            <div style={{ fontSize:'.72rem', fontWeight:700, color:'var(--text2)', textTransform:'uppercase', marginBottom:7, letterSpacing:'.06em' }}>📍 Ville</div>
            <select style={{ ...inp, width:'100%' }} value={filterVille} onChange={e => setFilterVille(e.target.value)}>
              <option value="">Toutes les villes</option>
              {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>

          <div>
            <div style={{ fontSize:'.72rem', fontWeight:700, color:'var(--text2)', textTransform:'uppercase', marginBottom:7, letterSpacing:'.06em' }}>📡 Mode</div>
            <select style={{ ...inp, width:'100%' }} value={filterMode} onChange={e => setFilterMode(e.target.value)}>
              <option value="">Tous les modes</option>
              <option value="en_ligne">🌐 En ligne</option>
              <option value="presentiel">🏫 Présentiel</option>
            </select>
          </div>

          <div>
            <div style={{ fontSize:'.72rem', fontWeight:700, color:'var(--text2)', textTransform:'uppercase', marginBottom:7, letterSpacing:'.06em' }}>📚 Matière</div>
            <select style={{ ...inp, width:'100%' }} value={filterMatiere} onChange={e => setFilterMatiere(e.target.value)}>
              <option value="">Toutes les matières</option>
              {allMatieres.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
          </div>

          <div>
            <div style={{ fontSize:'.72rem', fontWeight:700, color:'var(--text2)', textTransform:'uppercase', marginBottom:7, letterSpacing:'.06em' }}>💰 Budget max (DT/h)</div>
            <select style={{ ...inp, width:'100%' }} value={filterBudget} onChange={e => setFilterBudget(e.target.value)}>
              <option value="">Sans limite</option>
              {[20,30,40,50,75,100].map(b => <option key={b} value={b}>≤ {b} DT/h</option>)}
            </select>
          </div>

          {hasFilters && (
            <div style={{ display:'flex', alignItems:'flex-end' }}>
              <button onClick={resetFilters} style={{ width:'100%', padding:'9px', background:'rgba(255,101,132,0.1)', color:'#ff6584', border:'1px solid rgba(255,101,132,0.3)', borderRadius:10, cursor:'pointer', fontWeight:600, fontSize:'.82rem' }}>
                ✕ Réinitialiser
              </button>
            </div>
          )}
        </div>
      )}

      {/* ── RÉSULTATS ── */}
      <div style={{ fontSize:'.82rem', color:'var(--text2)', marginBottom:16 }}>
        <span style={{ fontWeight:700, color:'var(--text)' }}>{filtered.length}</span> résultat{filtered.length !== 1 ? 's' : ''}
        {(search || hasFilters) && ' pour votre recherche'}
      </div>

      {filtered.length === 0 ? (
        <div style={{ textAlign:'center', padding:'60px 20px', background:'var(--card)', borderRadius:24, border:'1px solid var(--border)' }}>
          <div style={{ fontSize:'3rem', marginBottom:14 }}>🔍</div>
          <h3 style={{ fontFamily:'Syne', margin:'0 0 8px' }}>Aucun professeur trouvé</h3>
          <p style={{ color:'var(--text2)', margin:'0 0 20px' }}>Essayez de modifier vos critères de recherche.</p>
          <button onClick={resetFilters} style={{ padding:'10px 24px', background:'linear-gradient(135deg,#6c63ff,#8b5cf6)', border:'none', borderRadius:12, fontWeight:700, cursor:'pointer', color:'#fff' }}>
            Voir tous les professeurs
          </button>
        </div>
      ) : vue === 'grille' ? (
        <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill, minmax(280px, 1fr))', gap:22 }}>
          {filtered.map(p => <ProfCard key={p.id} prof={p} onView={setSelectedProf} />)}
        </div>
      ) : (
        <div style={{ display:'flex', flexDirection:'column', gap:12 }}>
          {filtered.map(p => <ProfRow key={p.id} prof={p} onView={setSelectedProf} />)}
        </div>
      )}

      {/* ── MODAL ── */}
      {selectedProf && (
        <ProfModal prof={selectedProf} onClose={() => setSelectedProf(null)} />
      )}
    </div>
  );
}
